from typing import List

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.test_models.cloud.common import (enter_test_dedicated_state,
                                                                           exit_test_dedicated_state,
                                                                           cleanup_after_test_dedicated_state)


def general_siso_auto_cloud_entering_test_dedicated_state_and_running_nr_performance_pusch(testing_env: TestingEnv,
                                                                                           cells_names: List[str],
                                                                                           interval: float,
                                                                                           beam_pattern_id: List[int],
                                                                                           frc_index: str,
                                                                                           prb_offset: int,
                                                                                           digital_out_enable: bool,
                                                                                           digital_out_type: str,
                                                                                           digital_out_rate: str,
                                                                                           ru_mode: str,
                                                                                           mapping_type: str,
                                                                                           bb_selector: int,
                                                                                           uci_bits_number: int,
                                                                                           csi_bits_payload: List[int],
                                                                                           activate_high_speed_cell: bool,
                                                                                           start_timeout: int = 90,
                                                                                           stop_timeout: int = 90):
    """
    Based on:
    QC Test ID: 203675
    QC Test Name: [2.0] CB010411_L_Operability_CB007120_B_Entering_Test_Dedicated_State_and_run_NR_Performance_PUSCH_Via_Web

    Should report to:
    QC Test ID: 70649
    QC Test Name: General_SiSo_Auto_Cloud_Entering_Test_Dedicated_State_And_Running_NR_Performance_PUSCH

    :param testing_env: testing environment prepared for this test case
    :param cells_names: names of cells for which NR Performance PUSCH test (with same set of parameters) should be run;
                        can be taken from "NRCELL ID" field of cell details in DU WebEM;
                        i.e. ['NRCELL-1', 'NRCELL-3']
    :param interval: reporting time interval to be set before starting NR Performance PUSCH test; from <0.1, 3600> range
    :param beam_pattern_id: beam pattern ID to be set before starting NR Performance PUSCH test; i.e. [1, 1, 1, 1]
    :param frc_index: FRC index to be set before starting NR Performance PUSCH test; i.e. 'G-FR1-A5-9'
    :param prb_offset: PRB offset to be set before starting NR Performance PUSCH test; from <0, 272> range
    :param digital_out_enable: specifies whether digital output should be enabled before starting NR Performance PUSCH test;
                               if set to True then digital_out_type and digital_out_rate must be provided
    :param digital_out_type: digital output type to be set before starting NR Performance PUSCH test;
                             one of the following: 'SerialKeysight', 'SerialRs'
    :param digital_out_rate: digital output bit rate to be set before starting NR Performance PUSCH test;
                             one of the following: 'Bitrate_115dot2K', 'Bitrate_1dot92M', 'Bitrate_460dot8K'
    :param ru_mode: RU mode to be set before starting NR Performance PUSCH test; one of the following: 'NR_Only', 'MSR', 'Customize_1'
    :param mapping_type: UL DMRS mapping type to be set before starting NR Performance PUSCH test; one of the following: 'A', 'B'
    :param bb_selector: BB selector to be set before starting NR Performance PUSCH test; only valid if digital_out_type='SerialRs';
                        from <0, 3> range
    :param uci_bits_number: number of UCI bits to be set before starting NR Performance PUSCH test; from <0, 255> range
    :param csi_bits_payload: CSI bits payload to be set before starting NR Performance PUSCH test; list of maximum two items
    :param activate_high_speed_cell: specifies whether high speed cell should be activated before starting NR Performance PUSCH test
    :param start_timeout: timeout (in seconds) for starting NR Performance PUSCH test; defaults to 90
    :param stop_timeout: timeout (in seconds) for stopping NR Performance PUSCH test; defaults to 90
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    bts.cells.check_if_names_exist(names=cells_names)

    for du in bts.dus:
        enter_test_dedicated_state(du)

        for cell_name in cells_names:
            try:
                _start_nr_performance_pusch_test(du,
                                                 cell_name,
                                                 interval,
                                                 beam_pattern_id,
                                                 frc_index,
                                                 prb_offset,
                                                 digital_out_enable,
                                                 digital_out_type,
                                                 digital_out_rate,
                                                 ru_mode,
                                                 mapping_type,
                                                 bb_selector,
                                                 uci_bits_number,
                                                 csi_bits_payload,
                                                 activate_high_speed_cell,
                                                 start_timeout)
                _stop_nr_performance_pusch_test(du,
                                                cell_name,
                                                stop_timeout)
            except ResultError as exc:
                errors.add_from_exception(exc)

        exit_test_dedicated_state(du)

    errors.check()


def teardown_for_general_siso_auto_cloud_entering_test_dedicated_state_and_running_nr_performance_pusch(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    for du in bts.dus:
        cleanup_after_test_dedicated_state(du, errors)


def _start_nr_performance_pusch_test(du,
                                     cell_name,
                                     interval,
                                     beam_pattern_id,
                                     frc_index,
                                     prb_offset,
                                     digital_out_enable,
                                     digital_out_type,
                                     digital_out_rate,
                                     ru_mode,
                                     mapping_type,
                                     bb_selector,
                                     uci_bits_number,
                                     csi_bits_payload,
                                     activate_high_speed_cell,
                                     timeout):
    for cell in du.cells:
        if cell.name == cell_name:
            du.test_model.start_nr_performance_pusch_test(cell=cell,
                                                          interval=interval,
                                                          beam_pattern_id=beam_pattern_id,
                                                          frc_index=frc_index,
                                                          prb_offset=prb_offset,
                                                          digital_out_enable=digital_out_enable,
                                                          digital_out_type=digital_out_type,
                                                          digital_out_rate=digital_out_rate,
                                                          ru_mode=ru_mode,
                                                          mapping_type=mapping_type,
                                                          bb_selector=bb_selector,
                                                          uci_bits_number=uci_bits_number,
                                                          csi_bits_payload=csi_bits_payload,
                                                          activate_high_speed_cell=activate_high_speed_cell,
                                                          timeout=timeout)


def _stop_nr_performance_pusch_test(du, cell_name, timeout):
    for cell in du.cells:
        if cell.name == cell_name:
            du.test_model.stop_nr_performance_test(cell=cell,
                                                   timeout=timeout)
